"use strict";(globalThis.webpackChunkragflow_docs||=[]).push([[7107],{9384(e,n,t){t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>o,default:()=>h,frontMatter:()=>s,metadata:()=>i,toc:()=>c});const i=JSON.parse('{"id":"basics/rag","title":"What is Retrieval-Augmented-Generation (RAG)?","description":"Since large language models (LLMs) became the focus of technology, their ability to handle general knowledge has been astonishing. However, when questions shift to internal corporate documents, proprietary knowledge bases, or real-time data, the limitations of LLMs become glaringly apparent: they cannot access private information outside their training data. Retrieval-Augmented Generation (RAG) was born precisely to address this core need. Before an LLM generates an answer, it first retrieves the most relevant context from an external knowledge base and inputs it as \\"reference material\\" to the LLM, thereby guiding it to produce accurate answers. In short, RAG elevates LLMs from \\"relying on memory\\" to \\"having evidence to rely on,\\" significantly improving their accuracy and trustworthiness in specialized fields and real-time information queries.","source":"@site/../../docs/basics/rag.md","sourceDirName":"basics","slug":"/what-is-rag","permalink":"/docs/what-is-rag","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"slug":"/what-is-rag"},"sidebar":"tutorialSidebar","previous":{"title":"Basics","permalink":"/docs/category/basics"},"next":{"title":"What is Agent context engine?","permalink":"/docs/what-is-agent-context-engine"}}');var a=t(4848),r=t(8453);const s={sidebar_position:1,slug:"/what-is-rag"},o="What is Retrieval-Augmented-Generation (RAG)?",l={},c=[{value:"Why RAG is important?",id:"why-rag-is-important",level:2},{value:"How RAG works?",id:"how-rag-works",level:2},{value:"Data processing and vectorization",id:"data-processing-and-vectorization",level:3},{value:"Retrieve relevant information",id:"retrieve-relevant-information",level:3},{value:"Context construction and answer generation",id:"context-construction-and-answer-generation",level:3},{value:"Deep dive into existing RAG architecture: beyond vector retrieval",id:"deep-dive-into-existing-rag-architecture-beyond-vector-retrieval",level:2},{value:"Data complexity: multimodal document processing",id:"data-complexity-multimodal-document-processing",level:3},{value:"The complexity of chunking: the trade-off between precision and context",id:"the-complexity-of-chunking-the-trade-off-between-precision-and-context",level:3},{value:"Why is a vector database insufficient for serving RAG?",id:"why-is-a-vector-database-insufficient-for-serving-rag",level:3},{value:"RAG and memory: Retrieval from the same source but different streams",id:"rag-and-memory-retrieval-from-the-same-source-but-different-streams",level:2},{value:"RAG applications",id:"rag-applications",level:2},{value:"The future of RAG",id:"the-future-of-rag",level:2}];function d(e){const n={br:"br",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",ol:"ol",p:"p",ul:"ul",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"what-is-retrieval-augmented-generation-rag",children:"What is Retrieval-Augmented-Generation (RAG)?"})}),"\n",(0,a.jsx)(n.p,{children:'Since large language models (LLMs) became the focus of technology, their ability to handle general knowledge has been astonishing. However, when questions shift to internal corporate documents, proprietary knowledge bases, or real-time data, the limitations of LLMs become glaringly apparent: they cannot access private information outside their training data. Retrieval-Augmented Generation (RAG) was born precisely to address this core need. Before an LLM generates an answer, it first retrieves the most relevant context from an external knowledge base and inputs it as "reference material" to the LLM, thereby guiding it to produce accurate answers. In short, RAG elevates LLMs from "relying on memory" to "having evidence to rely on," significantly improving their accuracy and trustworthiness in specialized fields and real-time information queries.'}),"\n",(0,a.jsx)(n.h2,{id:"why-rag-is-important",children:"Why RAG is important?"}),"\n",(0,a.jsx)(n.p,{children:"Although LLMs excel in language understanding and generation, they have inherent limitations:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Static Knowledge: The model's knowledge is based on a data snapshot from its training time and cannot be automatically updated, making it difficult to perceive the latest information."}),"\n",(0,a.jsx)(n.li,{children:"Blind Spot to External Data: They cannot directly access corporate private documents, real-time information streams, or domain-specific content."}),"\n",(0,a.jsx)(n.li,{children:"Hallucination Risk: When lacking accurate evidence, they may still fabricate plausible-sounding but false answers to maintain conversational fluency."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:'The introduction of RAG provides LLMs with real-time, credible "factual grounding." Its core mechanism is divided into two stages:'}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Retrieval Stage: Based on the user's question, quickly retrieve the most relevant documents or data fragments from an external knowledge base."}),"\n",(0,a.jsx)(n.li,{children:"Generation Stage: The LLM organizes and generates the final answer by incorporating the retrieved information as context, combined with its own linguistic capabilities."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:'This upgrades LLMs from "speaking from memory" to "speaking with documentation," significantly enhancing reliability in professional and enterprise-level applications.'}),"\n",(0,a.jsx)(n.h2,{id:"how-rag-works",children:"How RAG works?"}),"\n",(0,a.jsx)(n.p,{children:"Retrieval-Augmented Generation enables LLMs to generate higher-quality responses by leveraging real-time, external, or private data sources through the introduction of an information retrieval mechanism. Its workflow can be divided into following key steps:"}),"\n",(0,a.jsx)(n.h3,{id:"data-processing-and-vectorization",children:"Data processing and vectorization"}),"\n",(0,a.jsx)(n.p,{children:"The knowledge required by RAG comes from unstructured data in various formats, such as documents, database records, or API return content. This data typically needs to be chunked, then transformed into vectors via an embedding model, and stored in a vector database."}),"\n",(0,a.jsx)(n.p,{children:"Why is Chunking Needed? Indexing entire documents directly faces the following problems:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:'Decreased Retrieval Precision: Vectorizing long documents leads to semantic "averaging," losing details.'}),"\n",(0,a.jsx)(n.li,{children:"Context Length Limitation: LLMs have a finite context window, requiring filtering of the most relevant parts for input."}),"\n",(0,a.jsx)(n.li,{children:"Cost and Efficiency: Embedding computation and retrieval costs are higher for long texts."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Therefore, an intelligent chunking strategy is key to balancing information integrity, retrieval granularity, and computational efficiency."}),"\n",(0,a.jsx)(n.h3,{id:"retrieve-relevant-information",children:"Retrieve relevant information"}),"\n",(0,a.jsx)(n.p,{children:"The user's query is also converted into a vector to perform semantic relevance searches (e.g., calculating cosine similarity) in the vector database, matching and recalling the most relevant text fragments."}),"\n",(0,a.jsx)(n.h3,{id:"context-construction-and-answer-generation",children:"Context construction and answer generation"}),"\n",(0,a.jsx)(n.p,{children:"The retrieved relevant content is added to the LLM's context as factual grounding, and the LLM finally generates the answer. Therefore, RAG can be seen as Context Engineering 1.0 for automated context construction."}),"\n",(0,a.jsx)(n.h2,{id:"deep-dive-into-existing-rag-architecture-beyond-vector-retrieval",children:"Deep dive into existing RAG architecture: beyond vector retrieval"}),"\n",(0,a.jsx)(n.p,{children:'An industrial-grade RAG system is far from being as simple as "vector search + LLM"; its complexity and challenges are primarily embedded in the retrieval process.'}),"\n",(0,a.jsx)(n.h3,{id:"data-complexity-multimodal-document-processing",children:"Data complexity: multimodal document processing"}),"\n",(0,a.jsx)(n.p,{children:"Core Challenge: Corporate knowledge mostly exists in the form of multimodal documents containing text, charts, tables, and formulas. Simple OCR extraction loses a large amount of semantic information."}),"\n",(0,a.jsx)(n.p,{children:'Advanced Practice: Leading solutions, such as RAGFlow, tend to use Visual Language Models (VLM) or specialized parsing models like DeepDoc to "translate" multimodal documents into unimodal text rich in structural and semantic information. Converting multimodal information into high-quality unimodal text has become standard practice for advanced RAG.'}),"\n",(0,a.jsx)(n.h3,{id:"the-complexity-of-chunking-the-trade-off-between-precision-and-context",children:"The complexity of chunking: the trade-off between precision and context"}),"\n",(0,a.jsx)(n.p,{children:'A simple "chunk-embed-retrieve" pipeline has an inherent contradiction:'}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Semantic Matching requires small text chunks to ensure clear semantic focus."}),"\n",(0,a.jsx)(n.li,{children:"Context Understanding requires large text chunks to ensure complete and coherent information."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:'This forces system design into a difficult trade-off between "precise but fragmented" and "complete but vague."'}),"\n",(0,a.jsx)(n.p,{children:"Advanced Practice: Leading solutions, such as RAGFlow, employ semantic enhancement techniques like constructing semantic tables of contents and knowledge graphs. These not only address semantic fragmentation caused by physical chunking but also enable the discovery of relevant content across documents based on entity-relationship networks."}),"\n",(0,a.jsx)(n.h3,{id:"why-is-a-vector-database-insufficient-for-serving-rag",children:"Why is a vector database insufficient for serving RAG?"}),"\n",(0,a.jsx)(n.p,{children:"Vector databases excel at semantic similarity search, but RAG requires precise and reliable answers, demanding more capabilities from the retrieval system:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"Hybrid Search: Relying solely on vector retrieval may miss exact keyword matches (e.g., product codes, regulation numbers). Hybrid search, combining vector retrieval with keyword retrieval (BM25), ensures both semantic breadth and keyword precision."}),"\n",(0,a.jsx)(n.li,{children:"Tensor or Multi-Vector Representation: To support cross-modal data, employing tensor or multi-vector representation has become an important trend."}),"\n",(0,a.jsx)(n.li,{children:"Metadata Filtering: Filtering based on attributes like date, department, and type is a rigid requirement in business scenarios."}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Therefore, the retrieval layer of RAG is a composite system based on vector search but must integrate capabilities like full-text search, re-ranking, and metadata filtering."}),"\n",(0,a.jsx)(n.h2,{id:"rag-and-memory-retrieval-from-the-same-source-but-different-streams",children:"RAG and memory: Retrieval from the same source but different streams"}),"\n",(0,a.jsx)(n.p,{children:"Within the agent framework, the essence of the memory mechanism is the same as RAG: both retrieve relevant information from storage based on current needs. The key difference lies in the data source:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"RAG: Targets pre-existing static or dynamic private data provided by the user in advance (e.g., documents, databases)."}),"\n",(0,a.jsx)(n.li,{children:'Memory: Targets dynamic data generated or perceived by the agent in real-time during interaction (e.g., conversation history, environmental state, tool execution results).\r\nThey are highly consistent at the technical base (e.g., vector retrieval, keyword matching) and can be seen as the same retrieval capability applied in different scenarios ("existing knowledge" vs. "interaction memory"). A complete agent system often includes both an RAG module for inherent knowledge and a Memory module for interaction history.'}),"\n"]}),"\n",(0,a.jsx)(n.h2,{id:"rag-applications",children:"RAG applications"}),"\n",(0,a.jsx)(n.p,{children:"RAG has demonstrated clear value in several typical scenarios:"}),"\n",(0,a.jsxs)(n.ol,{children:["\n",(0,a.jsxs)(n.li,{children:["Enterprise Knowledge Q&A and Internal Search",(0,a.jsx)(n.br,{}),"\n","By vectorizing corporate private data and combining it with an LLM, RAG can directly return natural language answers based on authoritative sources, rather than document lists. While meeting intelligent Q&A needs, it inherently aligns with corporate requirements for data security, access control, and compliance."]}),"\n",(0,a.jsxs)(n.li,{children:["Complex Document Understanding and Professional Q&A",(0,a.jsx)(n.br,{}),"\n","For structurally complex documents like contracts and regulations, the value of RAG lies in its ability to generate accurate, verifiable answers while maintaining context integrity. Its system accuracy largely depends on text chunking and semantic understanding strategies."]}),"\n",(0,a.jsxs)(n.li,{children:["Dynamic Knowledge Fusion and Decision Support",(0,a.jsx)(n.br,{}),"\n","In business scenarios requiring the synthesis of information from multiple sources, RAG evolves into a knowledge orchestration and reasoning support system for business decisions. Through a multi-path recall mechanism, it fuses knowledge from different systems and formats, maintaining factual consistency and logical controllability during the generation phase."]}),"\n"]}),"\n",(0,a.jsx)(n.h2,{id:"the-future-of-rag",children:"The future of RAG"}),"\n",(0,a.jsx)(n.p,{children:"The evolution of RAG is unfolding along several clear paths:"}),"\n",(0,a.jsxs)(n.ol,{children:["\n",(0,a.jsxs)(n.li,{children:["RAG as the data foundation for Agents",(0,a.jsx)(n.br,{}),"\n","RAG and agents have an architecture vs. scenario relationship. For agents to achieve autonomous and reliable decision-making and execution, they must rely on accurate and timely knowledge. RAG provides them with a standardized capability to access private domain knowledge and is an inevitable choice for building knowledge-aware agents."]}),"\n",(0,a.jsxs)(n.li,{children:["Advanced RAG: Using LLMs to optimize retrieval itself",(0,a.jsx)(n.br,{}),"\n","The core feature of next-generation RAG is fully utilizing the reasoning capabilities of LLMs to optimize the retrieval process, such as rewriting queries, summarizing or fusing results, or implementing intelligent routing. Empowering every aspect of retrieval with LLMs is key to breaking through current performance bottlenecks."]}),"\n",(0,a.jsxs)(n.li,{children:["Towards context engineering 2.0",(0,a.jsx)(n.br,{}),"\n",'Current RAG can be viewed as Context Engineering 1.0, whose core is assembling static knowledge context for single Q&A tasks. The forthcoming Context Engineering 2.0 will extend with RAG technology at its core, becoming a system that automatically and dynamically assembles comprehensive context for agents. The context fused by this system will come not only from documents but also include interaction memory, available tools/skills, and real-time environmental information. This marks the transition of agent development from a "handicraft workshop" model to the industrial starting point of automated context engineering.']}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"The essence of RAG is to build a dedicated, efficient, and trustworthy external data interface for large language models; its core is Retrieval, not Generation. Starting from the practical need to solve private data access, its technical depth is reflected in the optimization of retrieval for complex unstructured data. With its deep integration into agent architectures and its development towards automated context engineering, RAG is evolving from a technology that improves Q&A quality into the core infrastructure for building the next generation of trustworthy, controllable, and scalable intelligent applications."})]})}function h(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>s,x:()=>o});var i=t(6540);const a={},r=i.createContext(a);function s(e){const n=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),i.createElement(r.Provider,{value:n},e.children)}}}]);